def hold_back_crosstalk(act: dict[str, float], competitors: dict[str, tuple[float, frozenset[str]]]) -> dict[str, float]:
    """Hold a mapped gesture at 0 while another mapped gesture that shares none of its blendshapes is stronger than
    it by CROSSTALK_RATIO, both measured as level / on. A smile also lifts jawOpen, a wide-open mouth lifts the
    brows: the move the player meant is the one furthest past its own threshold, and the side effect lags well
    behind it. Two moves made on purpose together are both near full and both pass.
    competitors: gesture name -> (its on threshold, its blendshape sources; empty for learned moves)."""
    ratio = {name: act.get(name, 0.0) / on for name, (on, _) in competitors.items()}
    out = act
    for name, r in ratio.items():
        if r <= 0.0:
            continue
        sources = competitors[name][1]
        if any(other != name and r < config.CROSSTALK_RATIO * r_other and not (sources & competitors[other][1])
               for other, r_other in ratio.items()):
            if out is act:
                out = dict(act)
            out[name] = 0.0
    return out


# Profiles that ship in the repo (committed files): never deleted from the dashboard.
BUILT_IN_PROFILES = frozenset({"_defaults", "demo", "demo_webcam", "guest", "judge"})
_IDENTITY_FILES = ("identity.json", "identity_required.json", "identity.json.off")


def delete_profile_files(player: str) -> bool:
    """Delete a profile someone made here (its folder: calibration, mappings, moves, breath, Face ID). Built-in
    profiles are refused. True if there was a folder."""
    import re
    if player in BUILT_IN_PROFILES or player.startswith("_") or not re.fullmatch(r"[A-Za-z0-9_-]{1,32}", player):
        raise ValueError(f"{player!r} is a built-in profile and cannot be deleted")
    root = profiles._ROOT.resolve()
    folder = (root / player).resolve()
    if folder.parent != root:
        raise ValueError("not a profile folder")
    if not folder.is_dir():
        return False
    shutil.rmtree(folder)
    return True


def reset_profiles() -> list[str]:
    """Reset state: delete every profile someone made here, and every saved Face ID (also on built-in profiles).
    Built-in profiles and the default mappings stay. Returns the deleted profiles."""
    root = profiles._ROOT
    deleted = []
    if not root.is_dir():
        return deleted
    for folder in sorted(root.iterdir()):
        if not folder.is_dir():
            continue
        if folder.name in BUILT_IN_PROFILES or folder.name.startswith("_"):
            for name in _IDENTITY_FILES:
                (folder / name).unlink(missing_ok=True)
        else:
            shutil.rmtree(folder)
            deleted.append(folder.name)
    return deleted


def _face_box(landmarks) -> tuple[float, float, float, float]:
    p = np.asarray(landmarks, np.float32)
    return float(p[:, 0].min()), float(p[:, 1].min()), float(p[:, 0].max()), float(p[:, 1].max())


def _overlap(a: tuple, b: tuple) -> float:
    """Intersection over union of two (x0, y0, x1, y1) boxes."""
    w = max(0.0, min(a[2], b[2]) - max(a[0], b[0]))
    h = max(0.0, min(a[3], b[3]) - max(a[1], b[1]))
    inter = w * h
    union = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter
    return inter / union if union > 0 else 0.0


def forget_face(player: str) -> bool:
    """Turn Face ID off for a profile: its references and the "required" marker are moved aside (kept as
    identity.json.off for recovery, never shared: profiles/**/identity* is git-ignored). True if it had Face ID."""
    from helm import identity
    path = identity.identity_path(player)
    had = path.exists() or path.with_name("identity_required.json").exists()
    if path.exists():
        path.replace(path.with_name("identity.json.off"))
    path.with_name("identity_required.json").unlink(missing_ok=True)
    return had


def release_duplicate_faces(player: str, vectors: list) -> list[str]:
    """The same person enrolled in two profiles makes recognition "ambiguous" for both, forever (the gate needs a
    margin over every other enrolled profile). When `player` learns a face, any other profile whose references match
    it is unlocked. Returns those profiles."""
    from helm import identity
    new = np.stack([identity.unit(v) for v in vectors])
    released = []
    for path in sorted(profiles._ROOT.glob("*/identity.json")):
        other = path.parent.name
        if other == player:
            continue
        try:
            template = identity.load_template(path, other)
        except Exception:
            continue
        if float(np.median([template.score(v) for v in new])) >= identity.THRESHOLD:
            forget_face(other)
            released.append(other)
    return released


# Calibration steps where the player moves their head (not the expression steps): Face ID samples only these.
FACE_ID_STEPS = ("neutral", "yaw_left", "yaw_right", "pitch_up", "pitch_down")


class FaceEnrollment:
    """Face ID, learned during an ordinary full calibration of a named profile, with no step of its own (P3's
    `helm.identity` does the recognition; this replaces its command-line `enroll`). While the pipeline marks it
    `step` (one of FACE_ID_STEPS), a worker thread takes samples: FACE_ID_NEUTRAL_SAMPLES of the relaxed,
    straight-on face in the neutral step (what the player looks like while playing, so it must dominate), then up to
    FACE_ID_TURN_SAMPLES from each head turn within FACE_ID_MAX_TURN_DEG. A sample is kept only when exactly one face
    is in view. When the
    calibration ends the pipeline calls finish(): with at least FACE_ID_MIN_SAMPLES it saves them with
    `identity.save_template`. Nothing here runs on the pipeline thread."""

    def __init__(self, camera, player: str):
        self._camera, self.player = camera, player
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._finish = threading.Event()
        self.step: str | None = None               # set by the pipeline: the head-movement step running, or None
        self._samples = 0
        self.done = False
        self.saved = False
        self.reason = ""
        self.released: list[str] = []              # other profiles that held this same face and were unlocked
        self._thread = threading.Thread(target=self._run, name="face-id", daemon=True)

    def start(self) -> "FaceEnrollment":
        self._thread.start()
        return self

    def cancel(self) -> None:
        self._stop.set()

    def finish(self) -> None:
        """The calibration ended: stop sampling and save what was collected."""
        self._finish.set()

    @property
    def samples(self) -> int:
        with self._lock:
            return self._samples

    def _done(self, saved: bool, reason: str) -> None:
        with self._lock:
            self.saved, self.reason, self.done = saved, reason, True

    def _run(self) -> None:
        from helm import identity
        tracker = None
        try:
            encoder = identity.SFace()
            tracker = FaceTracker(num_faces=4)     # to tell "just you" from "someone else is in view"
            vectors, seq, next_at = [], -1, 0.0
            per_step: dict[str, int] = {}
            while not self._stop.is_set() and not self._finish.is_set():
                got = self._camera.wait_latest(seq, timeout=0.2)
                if got is None:
                    continue
                seq = got[2]
                step = self.step
                neutral = step == "neutral"
                quota = config.FACE_ID_NEUTRAL_SAMPLES if neutral else config.FACE_ID_TURN_SAMPLES
                if step is None or per_step.get(step, 0) >= quota or time.monotonic() < next_at:
                    continue
                image, capture_ns, seq = got
                next_at = time.monotonic() + (config.FACE_ID_NEUTRAL_INTERVAL_S if neutral else config.FACE_ID_TURN_INTERVAL_S)
                faces = tracker.process_all(image, capture_ns, seq)
                if len(faces) != 1:                # nobody, or someone else in view: not a reference
                    continue
                if not neutral and max(abs(faces[0].yaw), abs(faces[0].pitch)) > config.FACE_ID_MAX_TURN_DEG:
                    continue                       # turned further than anyone plays: a poor reference
                try:
                    vectors.append(encoder.embed(image, faces[0]))
                    per_step[step] = per_step.get(step, 0) + 1
                except ValueError:                 # too small or turned too far: not a usable reference
                    continue
                with self._lock:
                    self._samples = len(vectors)
            if self._stop.is_set():
                return self._done(False, "cancelled")
            if len(vectors) < config.FACE_ID_MIN_SAMPLES:
                return self._done(False, "Face ID needs one clear face in view while you turn your head; it was skipped")
            identity.save_template(self.player, vectors, provenance={"source": "calibration", "frames": len(vectors)})
            self.released = release_duplicate_faces(self.player, vectors)
            self._done(True, "")
        except FileNotFoundError:
            self._done(False, "Face ID model is not downloaded on this laptop (python -m helm.identity download)")
        except Exception as e:                     # never take calibration down with it
            log.warning("face id enrollment failed: %s", e)
            self._done(False, f"Face ID was skipped: {e}")
        finally:
            if tracker:
                tracker.close()


def _load_model(player: str) -> GestureModel | None:
    path = profiles.gesture_model_path(player)
    return GestureModel.load(path) if os.path.exists(path) else None


class SessionStats:
    """Per mapped gesture: fires, near-misses and the peak level of each attempt, for the coach and the dashboard.

    An attempt opens when the level reaches NEAR_MISS_RATIO of `on` and closes when it falls below half of `on`.
    A closed attempt that did not fire is a near-miss. Updated on the pipeline thread; read with summary().
    """

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._g: dict[str, dict] = {}
        self._active_s = 0.0
        self._last_t: float | None = None

    def update(self, act: dict[str, float], thresholds: dict[str, dict[str, float]], tracked: set[str],
               fired: tuple[str, ...], t_s: float, active: bool) -> None:
        dt = 0.0 if self._last_t is None else min(max(t_s - self._last_t, 0.0), 0.1)
        self._last_t = t_s
        if not active:                             # calibrating, recording, paused or face lost
            return
        with self._lock:
            self._active_s += dt
            for name in tracked:
                th = thresholds.get(name)
                if th is None:
                    continue
                level = act.get(name, 0.0)
                g = self._g.setdefault(name, {"fires": 0, "near_misses": 0, "peaks": deque(maxlen=50),
                                              "open": False, "peak": 0.0, "fired": False})
                g["on"], g["off"] = th["on"], th["off"]
                did_fire = name in fired
                if did_fire:
                    g["fires"] += 1
                if not g["open"]:
                    if level >= config.NEAR_MISS_RATIO * th["on"] or did_fire:
                        g["open"], g["peak"], g["fired"] = True, level, did_fire
                    continue
                g["peak"] = max(g["peak"], level)
                g["fired"] = g["fired"] or did_fire
                if level < 0.5 * th["on"]:
                    g["peaks"].append(round(g["peak"], 3))
                    if not g["fired"]:
                        g["near_misses"] += 1
                    g["open"] = False

    def summary(self) -> dict:
        with self._lock:
            minutes = self._active_s / 60.0
            return {
                "active_s": round(self._active_s, 1),
                "gestures": {name: {"fires": g["fires"], "near_misses": g["near_misses"],
                                    "fires_per_min": round(g["fires"] / minutes, 2) if minutes > 0 else 0.0,
                                    "peaks": list(g["peaks"]), "on": g.get("on"), "off": g.get("off")}
                             for name, g in self._g.items()},
            }


class Runtime:
    def __init__(self, args):
        self.args = args
        self.player: str = args.player
        self.game: str = args.game

        # Source: mock, replay, or camera + tracker.
        if args.mock:
            self._source = MockSource()
        elif args.replay:
            self._source = ReplaySource(args.replay)
        else:
            self._source = None
        self._camera = None if self._source else Camera(index=args.camera)
        self._tracker = None if self._source else FaceTracker()
        self._recorder = Recorder(args.record) if args.record else None
        self._last_seq = -1
        self._draw_preview = self._source is not None and not args.no_server   # cartoon frame for the dashboard

        # Stages, in pipeline order.
        self._pad = make_gamepad(args.output)
        self._sip = SipPuff(None if args.serial == "off" else args.serial)
        self._calib = profiles.load_calibration(self.player)
        self._apply_breath_range(self.player)
        self._mapping = profiles.load_mapping(self.player, self.game)
        self._model = _load_model(self.player)
        self._normalizer = Normalizer(self._calib)
        self._fatigue = FatigueTracker()
        self._mapper = Mapper(self._mapping)
        self._gestures: GestureEngine
        self._thresholds: dict[str, dict[str, float]] = {}
        self._competitors: dict[str, tuple[float, frozenset[str]]] = {}
        self._breath_levels: dict[str, float] = {}
        self._rebuild_gestures()

        # Pipeline-thread state.
        self._calibrator: Calibrator | None = None
        self._breath_cal: BreathCalibrator | None = None
        self._breath_accepted = False
        self._take_recorder: TakeRecorder | None = None
        self._last_idle = True
        self._last_face_ns = 0
        self._frames = 0
        self._seen_errors: set[str] = set()
        self._capture_times: deque[int] = deque(maxlen=config.STATS_WINDOW)
        self._vision_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._control_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._total_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._stats = SessionStats()               # per gesture, for the coach review
        self._fired_until: dict[str, int] = {}     # gesture or breath event -> perf_counter_ns it leaves "fired"

        # Shared with other threads: latest-value slots, plus commands and events that must not be dropped.
        self._lock = threading.Lock()
        self._requests: list[tuple[str, tuple]] = []
        self._events: list[dict] = []
        self._preview: tuple[np.ndarray, np.ndarray | None] | tuple[np.ndarray, None, list[dict]] | None = None
        self._dev_enabled = getattr(args, 'dev', False)
        self._dev_session = None
        self._dev_sessions = []
        self._dev_fit_threads = []
        self._dev_end_after_frame = False
        self._video_frame = None
        self._identity_worker = (IdentityWorker(self._camera, interval_s=config.IDENTITY_CHECK_INTERVAL_S)
                                 if self._camera else None)
        self._verified_box: tuple[float, float, float, float] | None = None   # the last verified face, followed
        self._verified_t = 0.0                     # monotonic time of the last "recognized" check
        self._face_id: FaceEnrollment | None = None   # Face ID learning during a full calibration
        self._face_id_relearning = False           # protection is off while that calibration runs
        self._identity_generation = 0
        self._identity_last_seq = -1
        self._identity_frame_seq = -1
        self._identity_admitted = False
        self._identity_clock_s = 0.0
        self._identity_last_capture_ns = None
        self._configure_identity()
        self._multiplayer = MultiplayerControllers(self._pad)
        self._multi_worker = MultiFaceWorker(self._camera) if self._camera else None
        self._multi_generation = 0
        self._multi_seq = -1
        self._assignment_versions = [0, 0]
        self._snapshot = self._build_snapshot(None, None, {}, ControlState(), None)

        self._stop = threading.Event()
        self._finished = threading.Event()         # set when a replay reaches its end
        self._thread: threading.Thread | None = None

    # ------------------------------------------------------------------ lifecycle

    def start(self) -> None:
        if self._camera:
            self._camera.start()
        if self._identity_worker:
            self._identity_worker.start()
        if self._multi_worker:
            self._multi_worker.start()
        self._sip.start()
        self._thread = threading.Thread(target=self._loop, name="pipeline", daemon=True)
        self._thread.start()
        threading.Thread(target=self._watch_profiles, name="profile-watch", daemon=True).start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread:
            self._thread.join(timeout=2.0)
        if self._identity_worker:
            self._identity_worker.close()
        if self._multi_worker:
            self._multi_worker.close()
        self._multiplayer.lose_all()
        if self._multiplayer.pads[1]:
            self._multiplayer.pads[1].close()
        self._cancel_face_id()
        closers = [lambda: self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns())), self._pad.close,
                   self._sip.stop]
        if self._camera:
            closers.append(self._camera.stop)
        if self._tracker:
            closers.append(self._tracker.close)
        if self._recorder:
            closers.append(self._recorder.close)
        for close in closers:
            try:
                close()
            except Exception:
                log.exception("error while stopping")
        if self._dev_session:
            self._dev_session.finish('shutdown')
            self._dev_session = None
        for worker in self._dev_fit_threads:
            worker.join()
        for recording in self._dev_sessions:
            recording.wait()
        snap = self._snapshot
        log.info("stopped after %d frames, %.1f fps, median total latency %.2f ms",
                 self._frames, snap["fps"], snap["latency_ms"]["total"])

    @property
    def finished(self) -> bool:
        return self._finished.is_set()

    # ------------------------------------------------------------------ called by server.py (asyncio thread)

    def start_calibration(self, mode: str) -> None:
        if mode not in ("full", "quick", "breath"):
            self._event("error",
                        {"message": f"calibration mode must be full, quick or breath, not {mode!r}"})
            return
        if mode == "breath" and not self._sip.connected:
            self._event("error", {"message": "No breath sensor is connected"})
            return
        self._request("calibrate", mode)

    def record_gesture(self, name: str) -> None:
        self._request("record", name)

    def record_negative(self) -> None:
        self._request("record", None)

    def delete_gesture(self, name: str) -> None:
        self._request("delete_gesture", name)

    def set_mapping(self, mapping: dict) -> list[str]:
        """Returns validation errors, empty if applied. A mapping set by hand may use any expression, including
        ones calibration found weak: the player chose it (the coach still sticks to reliable ones)."""
        calib = dataclasses.replace(self._calib, reliable=list(BLENDSHAPE_NAMES)) if self._calib else None
        errors = profiles.validate_mapping(mapping, calib, self._learned(), self._sip.connected)
        if not errors:                             # what the Mapper itself refuses, e.g. off above on in a hand edit
            try:
                Mapper(mapping)
            except (ValueError, TypeError, AttributeError) as e:
                errors.append(f"{type(e).__name__}: {e}")
        if not errors:
            self._request("set_mapping", mapping)
        return errors

    def load_profile(self, player: str, game: str) -> None:
        def load() -> None:
            calib = profiles.load_calibration(player)
            mapping = profiles.load_mapping(player, game)
            self._request("apply_profile", player, game, calib, mapping, _load_model(player))

        self._worker(load)

    def save_profile(self) -> None:
        def save() -> None:
            if self._calib:
                profiles.save_calibration(self._calib)
            profiles.save_mapping(self.player, self.game, self._mapping)
            if self._model:
                self._model.save(profiles.gesture_model_path(self.player))

        self._worker(save)

    def set_paused(self, on: bool) -> None:
        self._request("set_paused", on)

    def coach_build(self, game: str) -> None:
        self._captain(f"Set me up for {game}: give its most important actions my best moves, and keep every face "
                      "button (A, B, X, Y) on a gesture.", game, "build")

    def coach_review(self) -> None:
        self._captain("Review my session: fix gestures that fired by accident or were hard to trigger.", self.game,
                      "review")

    def coach_ask(self, request: str) -> None:
        self._captain(request, self.game, "ask")

    def _captain(self, request: str, game: str, kind: str) -> None:
        """The Captain on a worker: each step is a `captain_step` event, the answer a `coach_result` event."""
        def run() -> None:
            calib = self._calib or default_calibration(self.player)
            stats = {**self._stats.summary(), "notices": self._fatigue.notices()}
            result = coach.ask_captain(request, self._mapping, calib, self._learned(), self._sip.connected, game,
                                       stats=stats, on_step=lambda text: self._event("captain_step", {"text": text}),
                                       kind=kind)
            self._event("coach_result", {**result, "request": request, "kind": kind})

        self._event("captain_step", {"text": "Captain is on it", "start": True})
        self._worker(run)

    def snapshot(self) -> dict:
        """The "state" message of docs/SPEC.md section 8."""
        return self._snapshot

    def preview(self) -> tuple[np.ndarray, np.ndarray | None] | tuple[np.ndarray, None, list[dict]] | None:
        """Latest BGR frame and landmarks, with a third list of labeled faces in multiplayer.
        Mock/replay use a cartoon picture with no landmarks. None before the first frame."""
        return self._preview

    def pop_events(self) -> list[dict]:
        with self._lock:
            events, self._events = self._events, []
        return events

    # ------------------------------------------------------------------ helpers shared across threads

    def _request(self, kind: str, *args) -> None:
        with self._lock:
            self._requests.append((kind, args))

    def _event(self, name: str, data: dict) -> None:
        with self._lock:
            self._events.append({"type": "event", "name": name, "data": data})

    def _worker(self, fn, *args):
        """Run slow work (disk, coach) off the pipeline thread. Failures become "error" events."""
        def run() -> None:
            try:
                fn(*args)
            except Exception as e:
                log.exception("worker failed")
                self._event("error", {"message": f"{type(e).__name__}: {e}"})

        worker = threading.Thread(target=run, daemon=True)
        worker.start()
        return worker

    def _learned(self) -> list[str]:
        return self._model.names if self._model else []

    # ------------------------------------------------------------------ pipeline thread

    def _loop(self) -> None:
        while not self._stop.is_set():
            try:
                self._handle_requests()             # recovery/profile commands must work even when identity is locked
                if self._multiplayer.enabled:
                    self._multiplayer_tick()
                    continue
                f = self._next_features()
                if f is None:                      # no new frame (camera stalled): keep the pad safe
                    self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns()))
                    if self._identity_required:
                        self._snapshot = self._snapshot | {'identity': dict(self._identity_status)}
                    continue
                self._step(f)
            except Exception as e:
                key = f"{type(e).__name__}: {e}"
                if key not in self._seen_errors:
                    self._seen_errors.add(key)
                    log.exception("pipeline error (logged once): %s", key)
                try:
                    if self._multiplayer.enabled:
                        self._multiplayer.lose_all()
                    self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns()))
                except Exception:
                    pass

    def set_play_mode(self, mode: str) -> None:
        self._request('play_mode', mode)

    def _do_play_mode(self, mode: str) -> None:
        enabled = mode == 'multiplayer'
        if enabled == self._multiplayer.enabled:
            return
        self._multiplayer.lose_all()
        if enabled and self._multiplayer.pads[1] is None:
            try:
                self._multiplayer.pads[1] = second_gamepad(self._pad)
            except Exception as e:
                self._event('error', {'message': str(e)})
                return
        self._assignment_versions = [v + 1 for v in self._assignment_versions]
        self._multiplayer.sessions = [None, None]
        self._multiplayer.loading = [False, False]
        self._multiplayer.enabled = enabled
        self._multiplayer.error = None
        self._multi_seq = -1
        self._preview = None
        self._cancel_face_id()
        self._calibrator = self._take_recorder = self._breath_cal = None
        if self._dev_session:
            self._dev_session.finish('play_mode_changed')
            self._dev_session = None
        if self._multi_worker:
            self._multi_generation = self._multi_worker.configure(enabled)
        if enabled:
            if self._identity_worker:
                self._identity_worker.configure(None)
        else:
            self._configure_identity()
            self._reset_identity_controls()
        self._snapshot = self._build_snapshot(None, None, {}, ControlState(), None)

    def assign_controller(self, slot: int, player: str | None) -> None:
        self._request('assign_controller', slot, player)

    def _do_assign_controller(self, slot: int, player: str | None) -> None:
        if not self._multiplayer.enabled:
            self._event('error', {'message': 'Enable multiplayer before assigning a controller'})
            return
        if player is None:
            self._assignment_versions[slot] += 1
            self._multiplayer.assign(slot, None)
            return
        self._multiplayer.expire()
        if player not in self._multiplayer.visible:
            self._event('error', {'message': 'Choose a profile currently recognized in the camera'})
            return
        if any(s and s.player == player for i, s in enumerate(self._multiplayer.sessions) if i != slot):
            self._event('error', {'message': 'That profile already controls the other controller'})
            return
        self._assignment_versions[slot] += 1
        version = self._assignment_versions[slot]
        self._multiplayer.assign(slot, None)
        self._multiplayer.loading[slot] = True
        game, generation = self.game, self._multi_generation

        def prepare():
            try:
                session = load_player(player, game, hold_back_crosstalk)
                self._request('finish_assignment', slot, session, version, generation, None)
            except Exception as e:
                self._request('finish_assignment', slot, None, version, generation, str(e))
        self._worker(prepare)

    def _do_finish_assignment(self, slot, session, version, generation, error):
        if (not self._multiplayer.enabled or generation != self._multi_generation
                or version != self._assignment_versions[slot]):
            return
        self._multiplayer.loading[slot] = False
        self._multiplayer.expire()
        try:
            if error:
                raise ValueError(error)
            self._multiplayer.assign(slot, session)
        except Exception as e:
            self._event('error', {'message': str(e)})

    def _multiplayer_tick(self):
        if self._multi_worker is None:
            self._multiplayer.error = 'Multiplayer needs a live camera and face-enrolled profiles'
            self._multiplayer.lose_all()
            self._stop.wait(.05)
        else:
            result, error = self._multi_worker.wait_latest(self._multi_seq)
            if error:
                self._multiplayer.error = error
                self._multiplayer.lose_all()
                self._stop.wait(.05)
            elif result is not None and result.generation == self._multi_generation:
                self._multi_seq = result.seq
                if self._multiplayer.process(result):
                    overlays = [dict(player=result.matches.get(i), landmarks=f.landmarks)
                                for i, f in enumerate(result.faces)]
                    self._preview = (result.image, None, overlays)
            else:
                self._multiplayer.expire()
        self._sip.poll()                # the single physical breath sensor has no implicit multiplayer owner
        self._snapshot = self._build_snapshot(None, None, {}, ControlState(), None)

    def _next_features(self) -> FrameFeatures | None:
        if self._source is not None:
            f = self._source.next()
            if f is None:                          # replay ended
                self._finished.set()
                self._stop.set()
            elif self._draw_preview or self._dev_enabled:
                try:
                    self._video_frame = render_preview(f)
                    self._preview = (self._video_frame, None)
                except Exception:                  # e.g. no cv2: the dashboard shows its placeholder instead
                    self._draw_preview = False
                    log.exception("mock preview disabled")
            if self._identity_required and f is not None:
                self._identity_allowed = False
                self._identity_status.update(allowed=False, state='no_pixels',
                                             reason='Protected profiles require camera pixels; feature replay is locked')
            return f
        if self._identity_required:
            self._poll_identity()                  # never waits: the face check runs beside the tracker
        if self._camera is None:
            return None
        got = self._camera.wait_latest(self._last_seq, timeout=0.5)
        if got is None:
            return None
        bgr, t_capture_ns, seq = got
        self._last_seq = seq
        f = self._tracker.process(bgr, t_capture_ns, seq)
        self._video_frame = bgr
        self._preview = (bgr, f.landmarks)
        return f

    def _step(self, f: FrameFeatures) -> None:
        t_s = f.t_capture_ns / 1e9
        if self._recorder:
            self._recorder.write(f)                # memory only; the file is written on stop
        self._handle_requests()

        if self._identity_required:
            admitted = self._follow_verified(f)
            self._identity_allowed = admitted
            self._identity_status["allowed"] = admitted
            self._set_identity_admitted(admitted)
            if not admitted:
                self._identity_blocked_step(f)
                return
            if self._identity_last_capture_ns is not None:
                self._identity_clock_s += min(max((f.t_capture_ns-self._identity_last_capture_ns)/1e9, 0),
                                              config.CALIB_MAX_DT_S)
            self._identity_last_capture_ns = f.t_capture_ns
        enrollment_t_s = self._identity_clock_s if self._identity_required else t_s

        progress: Progress | None = None
        if self._calibrator is not None:
            progress = self._calibrator.feed(f, enrollment_t_s)
            if self._face_id is not None:
                self._face_id.step = progress.step if f.face and progress.step in FACE_ID_STEPS else None
            if progress.done:
                if self._face_id is not None:
                    self._face_id.finish()
                self._calib = self._calibrator.result()
                if self._dev_session:
                    self._dev_session.calibration(self._calib)
                    self._dev_end_after_frame = self._dev_session.kind == 'calibration'
                notes = self._calibrator.notes
                nod_takes, not_nod = self._calibrator.nod_samples()
                self._calibrator = None
                self._normalizer.set_calibration(self._calib)
                self._fatigue = FatigueTracker()   # levels are on a new scale: old baselines no longer compare
                self._rebuild_gestures()
                self._worker(profiles.save_calibration, self._calib)
                self._event("calibration_done", {"mode": self._calib.mode, "reliable": list(self._calib.reliable),
                                                 "range": {a: list(r) for a, r in self._calib.range.items()},
                                                 "notes": notes, "nod_takes": len(nod_takes)})
                if len(nod_takes) >= 2:            # the nod step's repetitions train the learned "nod_up" move
                    self._worker(self._prepare_nod, self._calib, dict(self._normalizer.gain), nod_takes, not_nod)
                # Breath range is measured straight after the face, while the player is still in
                # calibration mode, and only when a sensor is actually attached.
                if self._sip.connected:
                    self._breath_cal = BreathCalibrator(self._sip)
                    progress = self._breath_cal.feed(enrollment_t_s)
        if self._face_id is not None and self._calibrator is None and self._face_id.done:
            self._face_id_ended()
        if progress is None and self._breath_cal is not None:
            progress = self._breath_cal.feed(enrollment_t_s)
            if progress.done:
                max_puff, max_sip = self._breath_cal.result()
                notes = self._breath_cal.notes
                self._breath_accepted = self._breath_cal.accepted
                self._breath_cal = None
                self._sip.calibrate(max_puff, max_sip)
                # Only persist a real measurement. Writing the unchanged defaults would leave a
                # breath.json that looks calibrated and, worse, would override a future retune of
                # the config defaults with numbers nobody ever measured.
                if self._breath_accepted:
                    self._worker(profiles.save_breath, self.player, max_puff, max_sip)
                self._event("breath_calibration_done",
                            {"max_puff_mv": max_puff, "max_sip_mv": max_sip, "notes": notes,
                             "saved": self._breath_accepted})
                progress = None

        s = self._normalizer.update(f, breath=self._sip.level, idle=self._last_idle)

        if self._take_recorder is not None:
            progress = self._take_recorder.feed(s, enrollment_t_s)
            if progress.done:
                self._finish_recording()
                progress = None

        act = self._gestures.update(s)
        for name, sign in self._breath_levels.items():    # live breath: how hard, 0..1 of the player's range
            act[name] = max(0.0, sign * s.breath)
        act = hold_back_crosstalk(act, self._competitors)
        scales = self._fatigue.update(act, t_s)
        state = self._mapper.update(s, act, self._sip.poll(), scales)
        self._last_idle = self._mapper.idle

        now = time.perf_counter_ns()
        if f.face:
            self._last_face_ns = now
        face_lost = now - self._last_face_ns > config.FACE_LOST_MS * 1_000_000
        # The breath calibrator tells the player to sip and puff as hard as they can: without it
        # in this guard, the calibration sip slams the brake and the calibration puff latches the
        # throttle while they are doing it.
        neutral = (face_lost or self._calibrator is not None or self._breath_cal is not None
                   or self._take_recorder is not None or state.paused)
        out = ControlState(t_output_ns=state.t_output_ns, paused=state.paused) if neutral else state
        self._pad.apply(out)
        t_output_ns = time.perf_counter_ns()

        self._publish_processed(f, s, act, out, progress, neutral, t_output_ns)

    def _publish_processed(self, f, s, act, out, progress, neutral, t_output_ns):
        t_s = f.t_capture_ns / 1e9

        self._stats.update(act, self._thresholds, self._tracked, out.fired, t_s, active=not neutral)
        self._hold_fired(out.fired, t_output_ns)
        self._frames += 1
        self._capture_times.append(f.t_capture_ns)
        self._vision_ms.append((f.t_infer_ns - f.t_capture_ns) / 1e6)
        self._control_ms.append((t_output_ns - f.t_infer_ns) / 1e6)
        self._total_ms.append((t_output_ns - f.t_capture_ns) / 1e6)
        if self._dev_session:
            video = self._video_frame
            if video is None:
                video = render_preview(f)
            scores = self._model.predict(s.delta) if self._model else {'none': 1.0}
            if not self._dev_session.submit(video, f, s, act, scores, out, progress, identity=self._identity_status):
                self._event('error', {'message': self._dev_session.error or 'Dev recording stopped'})
                self._dev_end_after_frame = True
            if self._dev_end_after_frame:
                self._dev_session.finish('completed')
                self._dev_session = None
                self._dev_end_after_frame = False
        self._snapshot = self._build_snapshot(f, s, act, out, progress)

    def _poll_identity(self) -> None:
        """Pipeline, every frame of a protected profile: take the face check's newest result, if any. A
        "recognized" result marks that face (its box) as verified; a rejection, ambiguity, error or reload clears it,
        so control stops at once."""
        result, status = self._identity_worker.wait_latest(self._identity_last_seq, timeout=0)
        if result is not None and result.generation == self._identity_generation:
            self._identity_last_seq = result.frame.seq
            status = dict(result.status)
            if status.get("allowed") and result.frame.face and result.frame.landmarks is not None:
                self._verified_box = _face_box(result.frame.landmarks)
                self._verified_t = time.monotonic()
            elif status.get("state") != "confirming":
                self._verified_box = None
        elif status.get("state") in ("error", "loading"):
            self._verified_box = None
        elif self._verified_box is not None and status.get("state") in ("stale", "waiting"):
            status = {**self._identity_status, "state": "recognized"}   # between checks: still the verified face
        if self._verified_box is None or time.monotonic() - self._verified_t > config.IDENTITY_HOLD_S:
            self._identity_allowed = False
            self._set_identity_admitted(False)
        self._identity_status = {**status, "allowed": self._identity_allowed}

    def _follow_verified(self, f: FrameFeatures) -> bool:
        """Is this frame's face the verified one? Yes while the last "recognized" check is under IDENTITY_HOLD_S
        old and this face overlaps where the verified face was (then the box follows it as it moves)."""
        if (not f.face or f.landmarks is None or self._verified_box is None
                or time.monotonic() - self._verified_t > config.IDENTITY_HOLD_S):
            return False
        box = _face_box(f.landmarks)
        if _overlap(box, self._verified_box) < config.IDENTITY_FOLLOW_IOU:
            return False                           # another face took the tracker's attention
        self._verified_box = box
        return True

    def _configure_identity(self):
        self._verified_box = None
        # While a full calibration relearns this profile's face, the old references must not gate it: if they no
        # longer match (an old enrollment, new lighting), the calibration would wait forever for "the enrolled
        # person" and never learn the new face.
        self._identity_required = (self.player not in profiles.SHARED_PLAYERS and not self._face_id_relearning
                                   and identity_required(self.player))
        self._identity_allowed = not self._identity_required
        self._identity_status = unprotected_status(self.player)
        self._identity_last_seq = self._identity_frame_seq = -1
        self._identity_admitted = False
        self._identity_clock_s = 0.0
        self._identity_last_capture_ns = None
        if self._identity_worker:
            self._identity_generation = self._identity_worker.configure(self.player if self._identity_required else None)
        if self._identity_required:
            self._identity_status.update(protected=True, allowed=False, state='loading',
                                         face_landmarker_num_faces=4, reason='Loading face enrollment')
        if self._face_id_relearning:
            self._identity_status.update(state='relearning', reason='Learning your face in this calibration')
        if self._source is not None:
            self._identity_status['face_landmarker_num_faces'] = None

    def _reset_identity_controls(self):
        paused = getattr(self._mapper, '_paused', False)
        self._mapper = Mapper(self._mapping)
        self._mapper.set_paused(paused)
        self._normalizer = Normalizer(self._calib)
        self._fatigue = FatigueTracker()
        self._rebuild_gestures()
        self._last_idle = True
        self._last_face_ns = 0
        self._identity_last_capture_ns = None
        self._fired_until.clear()
        self._sip.poll()                            # discard events accumulated while somebody else was visible

    def _set_identity_admitted(self, admitted):
        if admitted != self._identity_admitted:
            self._reset_identity_controls()
        self._identity_admitted = admitted

    def _identity_blocked_step(self, f):
        """No grace period, breath, auto throttle, calibration sample or enrollment timer on rejection."""
        f = FrameFeatures(f.seq, f.t_capture_ns, f.t_infer_ns, False)
        s = Signals(f.seq, f.t_capture_ns, f.t_infer_ns, False,
                    {a: 0.0 for a in AXES}, np.zeros(52, np.float32), np.zeros(56, np.float32), 0.0)
        self._sip.poll()
        out = ControlState(t_output_ns=time.perf_counter_ns(), paused=getattr(self._mapper, '_paused', False))
        self._pad.apply(out)
        progress = self._paused_identity_progress()
        self._publish_processed(f, s, {}, out, progress, True, time.perf_counter_ns())

    def _paused_identity_progress(self):
        progress = None
        previous = self._snapshot.get('progress')
        if previous and (self._calibrator is not None or self._take_recorder is not None or self._breath_cal is not None):
            progress = Progress(**previous)
            progress.prompt = 'Waiting for the enrolled person; setup is paused'
        elif self._calibrator is not None or self._take_recorder is not None or self._breath_cal is not None:
            progress = Progress(True, 'identity', 'Waiting for the enrolled person; setup is paused', 0, 0)
        return progress

    def reload_identity(self):
        self._request('identity_reload')

    def delete_profile(self) -> None:
        """Delete the current profile (not a built-in one) and switch to Default."""
        player, game = self.player, self.game
        if player in BUILT_IN_PROFILES or player.startswith("_"):
            self._event("error", {"message": "Built-in profiles cannot be deleted"})
            return
        self.load_profile(profiles.GUEST_PLAYER, game)    # stop using it first, so nothing writes into it again

        def run() -> None:
            self._wait_for_player(profiles.GUEST_PLAYER)
            delete_profile_files(player)
            self._event("profile_deleted", {"player": player})

        self._worker(run)

    def reset_profiles(self) -> None:
        """Dev: delete every profile made here and every Face ID, then switch to Default."""
        game = self.game
        self.load_profile(profiles.GUEST_PLAYER, game)

        def run() -> None:
            self._wait_for_player(profiles.GUEST_PLAYER)
            deleted = reset_profiles()
            self._event("profiles_reset", {"deleted": deleted})

        self._worker(run)

    def _wait_for_player(self, player: str, timeout_s: float = 3.0) -> None:
        """Worker: wait until the pipeline has switched to `player` (a profile load lands on the next frame)."""
        deadline = time.monotonic() + timeout_s
        while self.player != player and time.monotonic() < deadline:
            time.sleep(0.02)

    def forget_face(self) -> None:
        """Turn Face ID off for the current profile (the Profile page's escape hatch)."""
        player = self.player
        if player in profiles.SHARED_PLAYERS:
            return

        def run() -> None:
            had = forget_face(player)
            self._request('identity_reload')
            self._event("face_id_forgotten", {"player": player, "had": had})

        self._worker(run)

    def _do_identity_reload(self):
        if self._multiplayer.enabled:
            self._multiplayer.lose_all()
            self._multi_seq = -1
            if self._multi_worker:
                self._multi_generation = self._multi_worker.configure(True)
            return
        self._configure_identity()
        self._reset_identity_controls()

    def _handle_requests(self) -> None:
        with self._lock:
            requests, self._requests = self._requests, []
        for kind, args in requests:
            getattr(self, "_do_" + kind)(*args)

    def set_dev_mode(self, on: bool) -> None:
        self._request('dev_mode', on)

    def set_dev_recording(self, on: bool) -> None:
        self._request('dev_recording', on)

    def _do_dev_mode(self, on: bool) -> None:
        if not on and self._dev_session:
            self._dev_session.finish('dev_mode_disabled')
            self._dev_session = None
        self._dev_enabled = on
        if on and self._calibrator:
            self._do_calibrate(self._calibrator.mode)
        elif on and self._take_recorder:
            self._start_dev_capture('gesture' if self._take_recorder.name else 'negative', self._take_recorder.name)

    def _do_dev_recording(self, on: bool) -> None:
        if on and self._multiplayer.enabled:
            raise ValueError('Open a player profile to record a dev dataset')
        if not self._dev_enabled:
            raise ValueError('Enable dev mode before recording a dataset')
        if on:
            if self._dev_session:
                raise ValueError('A dev recording is already active')
            self._start_dev_capture('manual')
        elif self._dev_session and self._dev_session.kind == 'manual':
            self._dev_session.finish('manual_stop')
            self._dev_session = None

    def _start_dev_capture(self, kind: str, label: str | None = None) -> None:
        if not self._dev_enabled:
            return
        if self._dev_session and self._dev_session.kind == 'manual':
            return
        if self._dev_session:
            self._dev_session.finish('replaced')
        self._dev_end_after_frame = False
        self._dev_session = DevRecording(getattr(self.args, 'dev_dir', 'artifacts/dev-datasets'), kind,
                                         self.player, self.game, self._calib or default_calibration(self.player),
                                         self._model.copy() if self._model else GestureModel(), self._mapping,
                                         source='mock' if self.args.mock else 'replay' if self.args.replay else 'camera',
                                         label=label)
        self._dev_sessions.append(self._dev_session)

    def _do_calibrate(self, mode: str) -> None:
        if self._multiplayer.enabled:
            raise ValueError('Open a player profile before calibrating')
        self._take_recorder = None
        if mode == "breath":
            # No dev capture: there is nothing facial to record, and labelling it 'calibration'
            # would put breath takes in the face dataset.
            self._calibrator = None
            self._breath_cal = BreathCalibrator(self._sip)
            return
        self._start_dev_capture('calibration')
        self._breath_cal = None
        self._cancel_face_id()
        self._calibrator = Calibrator(self.player, mode)
        # Face ID learns the player's face during this calibration's head-movement steps (named profiles only).
        if mode == "full" and self._face_id_possible():
            self._face_id = FaceEnrollment(self._camera, self.player).start()
            self._face_id_relearning = True
            self._configure_identity()
            self._reset_identity_controls()

    def _face_id_possible(self) -> bool:
        from helm import identity
        return (self._camera is not None and self.player not in profiles.SHARED_PLAYERS
                and identity.MODEL_PATH.exists())

    def _cancel_face_id(self) -> None:
        if self._face_id is not None:
            self._face_id.cancel()
            self._face_id = None
        if self._face_id_relearning:               # back to the profile's saved Face ID
            self._face_id_relearning = False
            self._configure_identity()
            self._reset_identity_controls()

    def _face_id_ended(self) -> None:
        """Pipeline, after the calibration: once Face ID has saved (or given up), protect the profile."""
        enrollment, self._face_id = self._face_id, None
        self._face_id_relearning = False
        self._event("face_id_done", {"saved": enrollment.saved, "reason": enrollment.reason,
                                     "samples": enrollment.samples, "released": enrollment.released})
        self._configure_identity()                 # from here on only this face controls the profile
        self._reset_identity_controls()

    def _do_record(self, name: str | None) -> None:
        if self._multiplayer.enabled:
            raise ValueError('Open a player profile before learning a gesture')
        self._cancel_face_id()
        self._start_dev_capture('gesture' if name else 'negative', name)
        self._calibrator = None
        self._breath_cal = None
        self._take_recorder = TakeRecorder(name)

    def _do_delete_gesture(self, name: str) -> None:
        if self._model and name in self._model.names:
            model = self._model.copy()
            model.remove(name)
            self._use_model(model, then=None)

    def _do_set_mapping(self, mapping: dict) -> None:
        self._mapping = mapping
        self._mapper.set_mapping(mapping)
        self._rebuild_gestures()

    def _do_apply_profile(self, player: str, game: str, calib, mapping: dict, model) -> None:
        if self._multiplayer.enabled:
            self._do_play_mode('singleplayer')
        if self._dev_session:
            self._dev_session.finish('profile_changed')
            self._dev_session = None
        self.player, self.game = player, game
        self._cancel_face_id()
        self._calibrator = self._take_recorder = None
        self._breath_cal = None
        self._apply_breath_range(player)
        self._calib, self._mapping, self._model = calib, mapping, model
        self._normalizer = Normalizer(calib)
        self._fatigue = FatigueTracker()
        self._mapper.set_mapping(mapping)
        self._rebuild_gestures()
        self._configure_identity()
        self._reset_identity_controls()
        self._stats = SessionStats()
        self._event("profile_loaded", {"player": player, "game": game})

    def _apply_breath_range(self, player: str) -> None:
        """This player's measured breath range, or the config defaults. Never inherited: a player
        with no breath.json must not keep the previous player's scale."""
        saved = profiles.load_breath(player)
        self._sip.calibrate(*(saved or (config.BREATH_MAX_PUFF_MV, config.BREATH_MAX_SIP_MV)))

    def _do_set_calibration(self, calib) -> None:
        self._calib = calib
        self._normalizer.set_calibration(calib)
        self._fatigue = FatigueTracker()
        self._rebuild_gestures()

    def _do_set_paused(self, on: bool) -> None:
        self._mapper.set_paused(on)

    def _finish_recording(self) -> None:
        recorder, self._take_recorder = self._take_recorder, None
        if self._dev_session and self._dev_session.kind in ('gesture', 'negative'):
            self._dev_end_after_frame = True
        model = self._model.copy() if self._model else GestureModel()
        for frames in recorder.result():
            if recorder.name is None:
                model.add_negative(frames)
            else:
                model.add_take(recorder.name, frames)
        for frames in recorder.rest:               # relaxed face between takes teaches "none"
            model.add_negative(frames)
        name = recorder.name or "none"

        def report(accuracy: dict[str, float]) -> None:
            score = accuracy.get(name)
            data = {"name": name, "accuracy": score}
            if recorder.name is not None and score is not None and score < config.MIN_TAKE_OUT_ACCURACY:
                data["message"] = (f"{name.replace('_', ' ')} was recognized in {round(score * 100)}% of "
                                   "held-out takes. Record it again to add takes, or make the movement more distinct.")
            self._event("gesture_trained", data)

        self._use_model(model, then=report)

    def _prepare_nod(self, calib, gains: dict[str, float], takes: list, not_nod: list) -> None:
        """Worker: turn the calibration's nod repetitions (and its not-a-nod steps) into model data, as the
        pipeline would have seen them with the new calibration, then hand the model to the pipeline thread."""
        def deltas(frames) -> np.ndarray:
            norm = Normalizer(calib)               # a fresh one per segment, like a recording starting
            norm.set_gains(gains)
            return np.stack([norm.update(f).delta for f in frames])

        model = self._model.copy() if self._model else GestureModel()
        model.remove(NOD_MOVE)                     # a new calibration replaces the old nods
        for frames in takes:
            model.add_take(NOD_MOVE, deltas(frames))
        for frames in not_nod:
            if frames:
                model.add_negative(deltas(frames))
        self._request("adopt_nod", model)

    def _do_adopt_nod(self, model: GestureModel) -> None:
        """Pipeline: use the model with the new nod, and put the nod on X when X is free or already had it."""
        def report(accuracy: dict[str, float]) -> None:
            self._event("gesture_trained", {"name": NOD_MOVE, "accuracy": accuracy.get(NOD_MOVE), "calibration": True})

        self._use_model(model, then=report)
        buttons = list(self._mapping.get("buttons") or [])
        on_x = next((b.get("gesture") for b in buttons if b.get("target") == "X"), None)
        if on_x not in (None, NOD_MOVE):
            return
        mapping = json.loads(json.dumps(self._mapping))
        mapping.setdefault("gestures", {})[NOD_MOVE] = {"kind": "learned", "on": config.LEARNED_ON, "off": config.LEARNED_OFF}
        mapping["buttons"] = [b for b in buttons if b.get("target") != "X"] + [{"gesture": NOD_MOVE, "target": "X", "mode": "tap"}]
        self._do_set_mapping(mapping)
        if self.player not in profiles.SHARED_PLAYERS:
            self._worker(profiles.save_mapping, self.player, self.game, mapping)

    def _use_model(self, model: GestureModel, then) -> None:
        """Switch to `model` now (it predicts with its previous classifier), fit it and save it on a worker.

        Fitting with leave-one-take-out takes up to about a second, too long for the pipeline thread.
        """
        self._model = model
        self._rebuild_gestures()
        path = profiles.gesture_model_path(self.player)

        dev_session = self._dev_session if self._dev_enabled else None
        dev_version = dev_session.model_update_started() if dev_session else None

        def fit_and_save() -> None:
            error = None
            try:
                accuracy = model.fit()
                if self._model is model:           # a newer recording or profile replaced it: keep that one
                    model.save(path)
                if dev_session:
                    dev_session.save_model(model, dev_version)
                if then:
                    then(accuracy)
            except Exception as e:
                error = e
                raise
            finally:
                if dev_session:
                    dev_session.model_update_finished(error)

        worker = self._worker(fit_and_save)
        if dev_session:
            self._dev_fit_threads.append(worker)

    def _rebuild_gestures(self) -> None:
        defs = self._mapping.get("gestures", {})
        self._gestures = GestureEngine(self._calib, defs, self._model)
        self._thresholds = {name: {"on": g["on"], "off": g["off"]}
                            for name, g in defs.items() if "on" in g and "off" in g}
        self._tracked = {b["gesture"] for b in self._mapping.get("buttons", []) if "gesture" in b}
        used = self._tracked | {t.get("source") for t in self._mapping.get("triggers", []) or []}
        pause = (self._mapping.get("pause") or {}).get("gesture")
        gains: dict[str, float] = {}
        for axis in self._mapping.get("axes", []) or []:
            if isinstance(axis, dict) and axis.get("source") in AXES and isinstance(axis.get("gain"), (int, float)):
                gains.setdefault(axis["source"], float(axis["gain"]))
        self._normalizer.set_gains(gains)
        self._competitors = {
            name: (float(g["on"]), frozenset(g.get("sources", []) if g.get("kind") == "blendshape" else ()))
            for name, g in defs.items()
            if name in used and name != pause and g.get("kind") in ("blendshape", "learned")
            and isinstance(g.get("on"), (int, float)) and g["on"] > 0}
        # Live breath gestures ("breath_level"): their level is the pressure itself, so they press as soon as the
        # breath passes `on` (no wait for the release, unlike the soft/hard events) and work with hold and analog.
        self._breath_levels = {name: BREATH_LEVEL_SIGN[name] for name, g in defs.items()
                               if g.get("kind") == "breath_level" and name in BREATH_LEVEL_SIGN}
        self._catalog_key = None                   # the editor's gesture list is rebuilt on the next snapshot

    def _watch_profiles(self) -> None:
        """Apply hand edits to profiles/<player>/calibration.json and profiles/<player>/<game>.json while running
        (docs/TUNING.md). Polls the files' times once a second, off the pipeline thread. A file that does not parse
        or validate is reported as an error event and not applied. Helm's own saves change nothing."""
        seen: dict[Path, int | None] = {}
        reported: set[str] = set()
        while not self._stop.wait(config.PROFILE_WATCH_S):
            try:
                self._check_profile_files(seen)
            except Exception as e:
                key = f"{type(e).__name__}: {e}"
                if key not in reported:
                    reported.add(key)
                    log.exception("profile watch failed")

    def _check_profile_files(self, seen: dict) -> None:
        folder = Path(profiles.gesture_model_path(self.player)).parent
        for kind, path in (("calibration", folder / "calibration.json"), ("mapping", folder / f"{self.game}.json"),
                           ("breath", folder / "breath.json")):
            try:
                mtime = path.stat().st_mtime_ns
            except OSError:
                mtime = None
            first, changed = path not in seen, seen.get(path) != mtime
            seen[path] = mtime
            if first or not changed or mtime is None:  # first look (or a new player or game) only takes a baseline
                continue
            try:
                data = json.loads(path.read_text())
            except (OSError, ValueError) as e:
                self._event("error", {"message": f"{path.name} was not applied, it does not read as JSON: {e}"})
                continue
            if kind == "breath":
                scales = profiles.load_breath(self.player)
                if scales is None:
                    if self.player not in profiles.SHARED_PLAYERS:
                        self._event("error", {"message": f"{path.name} was not applied: it needs max_puff_mv and "
                                                         "max_sip_mv, both positive numbers"})
                    continue
                if tuple(scales) == tuple(self._sip.scales):
                    continue
                self._sip.calibrate(*scales)       # thread-safe: the sensor applies it under its own lock
            elif kind == "calibration":
                calib = profiles.load_calibration(self.player)
                if calib is None:
                    if self.player not in profiles.SHARED_PLAYERS:
                        self._event("error", {"message": f"{path.name} was not applied: a field is missing or has "
                                                         "the wrong shape (see docs/TUNING.md)"})
                    continue
                if calib == self._calib:
                    continue
                self._request("set_calibration", calib)
            else:
                if data == self._mapping:
                    continue
                errors = self.set_mapping(data)
                if errors:
                    self._event("error", {"message": f"{path.name} was not applied: " + "; ".join(errors[:3])})
                    continue
            log.info("applied hand edits to %s", path)
            self._event("profile_reloaded", {"file": f"profiles/{self.player}/{path.name}", "what": kind})

    def _gesture_catalog(self) -> dict:
        """What the mapping editor can use. Cached: rebuilt only when calibration, moves, game or breath change."""
        key = (id(self._calib), tuple(self._learned()), self._sip.connected, self.game)
        if key != self._catalog_key:
            calib = self._calib or default_calibration(self.player)
            self._catalog = coach.gesture_catalog(calib, self._learned(), self._sip.connected, self.game)
            self._catalog_key = key
        return self._catalog

    def _hold_fired(self, fired: tuple[str, ...], now_ns: int) -> list[str]:
        """Keep each fire for FIRED_HOLD_MS: a fire lasts one tick, but the dashboard samples states at 30 Hz."""
        until = now_ns + config.FIRED_HOLD_MS * 1_000_000
        held = {name: t for name, t in self._fired_until.items() if t > now_ns}
        for name in fired:
            held[name] = until
        self._fired_until = held
        return list(held)

    def _build_snapshot(self, f: FrameFeatures | None, s: Signals | None, act: dict[str, float],
                        out: ControlState, progress: Progress | None) -> dict:
        times = self._capture_times
        span_s = (times[-1] - times[0]) / 1e9 if len(times) > 1 else 0.0
        fps = (len(times) - 1) / span_s if span_s > 0 else 0.0

        def median(values: deque) -> float:
            return round(statistics.median(values), 2) if values else 0.0

        return {
            "type": "state",
            "fps": round(fps, 1),
            "latency_ms": {"vision": median(self._vision_ms), "control": median(self._control_ms),
                           "total": median(self._total_ms)},
            "face": bool(f.face) if f else False,
            "paused": out.paused,
            "breath_connected": self._sip.connected,
            "profile": {"player": self.player, "game": self.game,
                        "calibrated": self._calib.mode if self._calib else None},
            "identity": dict(self._identity_status),
            "raw": {a: float(getattr(f, a)) if f else 0.0 for a in AXES},
            "axes": {a: float(s.axes[a]) if s else 0.0 for a in AXES},
            "breath": float(s.breath) if s else 0.0,
            "breath_marks": {"soft": config.BREATH_SOFT, "hard": config.BREATH_HARD},
            "ranges": {a: [round(lo, 1), round(hi, 1)] for a, (lo, hi) in self._normalizer.effective_range().items()},
            "activations": {name: float(level) for name, level in act.items()},
            "thresholds": self._thresholds,
            "control": {"lx": out.lx, "ly": out.ly, "rx": out.rx, "ry": out.ry, "lt": out.lt, "rt": out.rt,
                        "buttons": sorted(out.buttons)},
            "fired": list(self._fired_until),      # held for FIRED_HOLD_MS, see _hold_fired
            "progress": dataclasses.asdict(progress) if progress else None,
            "gestures": {"learned": self._learned(), "reliable": list(self._calib.reliable) if self._calib else []},
            "notices": self._fatigue.notices(),
            "mapping": self._mapping,
            "expressions": {n: float(f.blend[_BLEND_INDEX[n]]) if f and f.face else 0.0 for n in config.WATCH_EXPRESSIONS},
            "catalog": self._gesture_catalog(),
            "dev": {"enabled": self._dev_enabled, "recording": self._dev_session is not None,
                    "session": self._dev_sessions[-1].status() if self._dev_sessions else None},
            "multiplayer": self._multiplayer.snapshot(),
        }


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    p = argparse.ArgumentParser(prog="python -m helm", description="Helm: hands-free game controller")
    source = p.add_mutually_exclusive_group()
    source.add_argument("--mock", action="store_true", help="synthetic face data instead of the camera")
    source.add_argument("--replay", metavar="PATH", help="replay a recorded .npz instead of the camera")
    p.add_argument('--dev', action='store_true', help='Save calibration/enrollment video and enable debug datasets')
    p.add_argument('--dev-dir', default='artifacts/dev-datasets', help='Local development dataset directory')
    p.add_argument("--record", metavar="PATH", help="save FrameFeatures to a .npz while running")
    p.add_argument("--output", choices=("auto", "vgamepad", "keyboard", "null"), default="auto")
    p.add_argument("--player", default="guest", metavar="NAME")
    p.add_argument("--game", default="SuperTuxKart", metavar="NAME")
    p.add_argument("--camera", type=int, default=0, metavar="N")
    p.add_argument("--port", type=int, default=config.SERVER_PORT)
    p.add_argument("--no-server", action="store_true", help="run the pipeline without the dashboard server")
    p.add_argument("--seconds", type=float, default=None, metavar="N", help="stop after N seconds (with --no-server)")
    p.add_argument("--serial", default="auto", metavar="PORT|auto|off")
    p.add_argument("--no-build", action="store_true", help="do not rebuild the dashboard when its source changed")
    return p.parse_args(argv)


UI_DIR = Path(__file__).resolve().parent.parent / "ui"


def ensure_dashboard(ui: Path = UI_DIR) -> bool:
    """Rebuild ui/dist when the dashboard's source is newer than the build (for example after a git pull), so
    http://localhost:8000 never serves an old page. Runs `npm install` first when the dependencies changed.
    Returns True when the build is current. Without npm, or if the build fails, logs how to fix it and goes on."""
    dist = ui / "dist" / "index.html"
    sources = [p for p in (ui / "src").rglob("*") if p.is_file()]
    sources += [p for p in (ui / "index.html", ui / "package.json", ui / "package-lock.json", ui / "vite.config.ts")
                if p.exists()]
    if not sources:
        return dist.exists()
    if dist.exists() and dist.stat().st_mtime >= max(p.stat().st_mtime for p in sources):
        return True
    npm = shutil.which("npm")
    if not npm:
        log.warning("the dashboard is out of date and npm was not found: run `cd ui && npm install && npm run build`")
        return False
    flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
    installed = ui / "node_modules" / ".package-lock.json"
    lock = ui / "package-lock.json"
    steps = []
    if not installed.exists() or (lock.exists() and lock.stat().st_mtime > installed.stat().st_mtime):
        steps.append([npm, "install", "--no-audit", "--no-fund"])
    steps.append([npm, "run", "build"])
    log.info("the dashboard changed since it was last built: building it now (a few seconds)")
    for cmd in steps:
        try:
            proc = subprocess.run(cmd, cwd=ui, capture_output=True, text=True, timeout=300, creationflags=flags)
        except (OSError, subprocess.TimeoutExpired) as e:
            log.warning("dashboard build failed (%s): run `cd ui && npm install && npm run build`", e)
            return False
        if proc.returncode != 0:
            tail = (proc.stdout + proc.stderr).strip().splitlines()[-8:]
            log.warning("dashboard build failed: `%s` exited %s:\n%s", " ".join(cmd[1:]), proc.returncode, "\n".join(tail))
            return False
    log.info("dashboard built")
    return True


def main() -> None:
    args = parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s %(levelname)s %(message)s")
    if not args.no_server and not args.no_build:
        ensure_dashboard()
    runtime = Runtime(args)
    runtime.start()
    try:
        if args.no_server:
            deadline = None if args.seconds is None else time.monotonic() + args.seconds
            while not runtime.finished and (deadline is None or time.monotonic() < deadline):
                time.sleep(0.05)
        else:
            from helm import server            # imported here so --no-server runs without FastAPI

            server.run(runtime, port=args.port)
    except KeyboardInterrupt:
        pass
    finally:
        runtime.stop()
